class Buffer
{
public:
    explicit Buffer(int value)
        : data_(new int(value))
    {
    }

    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;

    ~Buffer()
    {
        delete data_;
    }

    bool empty() const
    {
        return data_ == nullptr;
    }

    int value() const
    {
        return data_ ? *data_ : 0;
    }

private:
    int* data_;
};

reference_solution:
class Buffer
{
public:
    explicit Buffer(int value)
        : data_(new int(value))
    {
    }

    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;

    Buffer(Buffer&& other) noexcept
        : data_(other.data_)
    {
        other.data_ = nullptr;
    }

    ~Buffer()
    {
        delete data_;
    }

    bool empty() const
    {
        return data_ == nullptr;
    }

    int value() const
    {
        return data_ ? *data_ : 0;
    }

private:
    int* data_;
};
